const BLOCKED_ELEMENTS = new Set([
    'a', 'animate', 'animatemotion', 'animatetransform', 'audio', 'discard', 'embed', 'foreignobject', 'iframe', 'image',
    'link', 'object', 'script', 'set', 'video',
])
const XML_DECLARATION_PATTERN = /<!DOCTYPE|<!ENTITY/iu
const CSS_EXTERNAL_PATTERN = /@import|url\s*\(/iu

function isExternalReference(value: string) {
    const trimmed = value.trim()

    return trimmed.length > 0 && trimmed[0] !== '#'
}

/** Parses standalone SVG as XML and returns safe inline markup. */
export function sanitizeDiagramSvg(svg: string) {
    if (XML_DECLARATION_PATTERN.test(svg)) throw new Error('Unsafe SVG: declarations and entities are not allowed')
    const document = new DOMParser().parseFromString(svg, 'image/svg+xml')
    if (document.querySelector('parsererror')) throw new Error('Invalid SVG XML')
    const root = document.documentElement
    if (root.localName.toLowerCase() !== 'svg') throw new Error('Diagram output must be a standalone SVG')

    const interactiveIds = new Set<string>()
    for (const element of [root, ...root.querySelectorAll('*')]) {
        if (BLOCKED_ELEMENTS.has(element.localName.toLowerCase())) {
            element.remove()
            continue
        }
        if (element.localName.toLowerCase() === 'style' && CSS_EXTERNAL_PATTERN.test(element.textContent ?? '')) {
            element.remove()
            continue
        }
        for (const attribute of [...element.attributes]) {
            const name = attribute.name.toLowerCase()
            const value = attribute.value
            if (name.startsWith('on') || name === 'src' || name === 'xml:base' || CSS_EXTERNAL_PATTERN.test(value)) {
                element.removeAttribute(attribute.name)
                continue
            }
            if ((name === 'href' || name === 'xlink:href') && isExternalReference(value)) element.removeAttribute(attribute.name)
        }
        const itemId = element.getAttribute('data-diagram-id')?.trim() ?? ''
        const itemLabel = element.getAttribute('data-diagram-label')?.trim() ?? ''
        if (itemId.length === 0 && itemLabel.length === 0) continue
        if (itemId.length === 0 || itemLabel.length === 0) throw new Error('Interactive SVG items require data-diagram-id and data-diagram-label')
        if (interactiveIds.has(itemId)) throw new Error(`Duplicate interactive SVG ID: ${itemId}`)
        interactiveIds.add(itemId)
        element.setAttribute('data-diagram-id', itemId)
        element.setAttribute('data-diagram-label', itemLabel)
        if (!element.hasAttribute('aria-label')) element.setAttribute('aria-label', itemLabel)
    }

    return new XMLSerializer().serializeToString(root)
}

